   125  long parse_long(const char *value, long default_value)
   126  {
   127      char *endptr;
   128      long parsed;
   129
   130      errno = 0;
   131      parsed = strtol(value, &endptr, 0);
   132
   133      if (errno != 0)
   134          return default_value;
   135
   136      if (*endptr != '\0' || value == endptr)
   137          return default_value;
   138
   139      return parsed;
   140  }
