   152  bool parse_bool(const char *value, bool default_value)
   153  {
   154      if (!value)
   155          return default_value;
   156
   157      if (streq(value, "true") || streq(value, "on") || streq(value, "yes"))
   158          return true;
   159
   160      if (streq(value, "false") || streq(value, "off") || streq(value, "no"))
   161          return false;
   162
   163      return parse_int(value, default_value);
   164  }
