   166  bool config_error(struct config *conf, const char *fmt, ...)
   167  {
   168      va_list values;
   169      int len;
   170      char *output;
   171
   172      if (conf->error_message)
   173          return false;
   174
   175      va_start(values, fmt);
   176      len = vasprintf(&output, fmt, values);
   177      va_end(values);
   178
   179      if (len >= 0) {
   180          conf->error_message = output;
   181          return true;
   182      }
   183
   184      conf->error_message = NULL;
   185      return false;
   186  }
