   496  static void *parse_key_value(struct parser *parser)
   497  {
   498      struct config_line line = {.type = CONFIG_LINE_TYPE_LINE};
   499      struct lexeme *lexeme;
   500      size_t key_size;
   501
   502      while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
   503          lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   504                                 lexeme->value.len);
   505
   506          if (!lexeme_ring_buffer_empty(&parser->buffer))
   507              lwan_strbuf_append_char(&parser->strbuf, '_');
   508      }
   509      key_size = lwan_strbuf_get_length(&parser->strbuf);
   510      lwan_strbuf_append_char(&parser->strbuf, '\0');
   511
   512      while (lex_next(&parser->lexer, &lexeme)) {
   513          switch (lexeme->type) {
   514          case LEXEME_VARIABLE_DEFAULT:
   515          case LEXEME_VARIABLE: {
   516              const char *value;
   517
   518              value = secure_getenv_len(lexeme->value.value, lexeme->value.len);
   519              if (lexeme->type == LEXEME_VARIABLE) {
   520                  if (!value) {
   521                      lwan_status_error(
   522                          "Variable '$%.*s' not defined in environment",
   523                          (int)lexeme->value.len, lexeme->value.value);
   524                      return NULL;
   525                  } else {
   526                      lwan_strbuf_append_str(&parser->strbuf, value, 0);
   527                  }
   528              } else {
   529                  struct lexeme *var_name = lexeme;
   530
   531                  if (!lex_next(&parser->lexer, &lexeme)) {
   532                      lwan_status_error(
   533                          "Default value for variable '$%.*s' not given",
   534                          (int)var_name->value.len, var_name->value.value);
   535                      return NULL;
   536                  }
   537
   538                  if (lexeme->type != LEXEME_STRING) {
   539                      lwan_status_error("Wrong format for default value");
   540                      return NULL;
   541                  }
   542
   543                  if (!value) {
   544                      lwan_status_debug(
   545                          "Using default value of '%.*s' for variable '${%.*s}'",
   546                          (int)lexeme->value.len, lexeme->value.value,
   547                          (int)var_name->value.len, var_name->value.value);
   548                      lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   549                                             lexeme->value.len);
   550                  } else {
   551                      lwan_strbuf_append_str(&parser->strbuf, value, 0);
   552                  }
   553              }
   554
   555              break;
   556          }
   557
   558          case LEXEME_EQUAL:
   559              lwan_strbuf_append_char(&parser->strbuf, '=');
   560              break;
   561
   562          case LEXEME_STRING:
   563              lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
   564                                     lexeme->value.len);
   565              break;
   566
   567          case LEXEME_CLOSE_BRACKET:
   568              backup(&parser->lexer);
   569              /* fallthrough */
   570
   571          case LEXEME_LINEFEED:
   572              line.key = lwan_strbuf_get_buffer(&parser->strbuf);
   573              line.value = line.key + key_size + 1;
   574              if (!config_buffer_emit(&parser->items, &line))
   575                  return NULL;
   576
   577              return parse_config;
   578
   579          default:
   580              lwan_status_error("Unexpected token while parsing key-value: %s",
   581                                lexeme_type_str[lexeme->type]);
   582              return NULL;
   583          }
   584      }
   585
   586      lwan_status_error("EOF while parsing key-value");
   587      return NULL;
   588  }
