   590  static void *parse_section(struct parser *parser)
   591  {
   592      struct lexeme *lexeme;
   593      size_t name_len;
   594
   595      if (!lexeme_buffer_consume(&parser->buffer, &lexeme))
   596          return NULL;
   597
   598      lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
   599      name_len = lexeme->value.len;
   600      lwan_strbuf_append_char(&parser->strbuf, '\0');
   601
   602      while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
   603          lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
   604
   605          if (!lexeme_ring_buffer_empty(&parser->buffer))
   606              lwan_strbuf_append_char(&parser->strbuf, ' ');
   607      }
   608
   609      struct config_line line = {
   610          .type = CONFIG_LINE_TYPE_SECTION,
   611          .key = lwan_strbuf_get_buffer(&parser->strbuf),
   612          .value = lwan_strbuf_get_buffer(&parser->strbuf) + name_len + 1
   613      };
   614      if (!config_buffer_emit(&parser->items, &line))
   615          return NULL;
   616
   617      return parse_config;
   618  }
