   620  static void *parse_section_shorthand(struct parser *parser)
   621  {
   622      void *next_state = parse_section(parser);
   623
   624      if (next_state) {
   625          struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
   626
   627          if (!config_buffer_emit(&parser->items, &line))
   628              return NULL;
   629
   630          return next_state;
   631      }
   632
   633      return NULL;
   634  }
