   636  static void *parse_config(struct parser *parser)
   637  {
   638      struct lexeme *lexeme;
   639
   640      if (!lex_next(&parser->lexer, &lexeme))
   641          return NULL;
   642
   643      switch (lexeme->type) {
   644      case LEXEME_EQUAL:
   645          return parse_key_value;
   646
   647      case LEXEME_OPEN_BRACKET:
   648          return parse_section;
   649
   650      case LEXEME_LINEFEED:
   651          if (!lexeme_ring_buffer_empty(&parser->buffer))
   652              return parse_section_shorthand;
   653
   654          return parse_config;
   655
   656      case LEXEME_STRING:
   657          lexeme_buffer_emit(&parser->buffer, lexeme);
   658
   659          return parse_config;
   660
   661      case LEXEME_CLOSE_BRACKET: {
   662          struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
   663
   664          config_buffer_emit(&parser->items, &line);
   665
   666          return parse_config;
   667      }
   668
   669      case LEXEME_EOF:
   670          return NULL;
   671
   672      default:
   673          lwan_status_error("Unexpected lexeme type: %s",
   674              lexeme_type_str[lexeme->type]);
   675          return NULL;
   676      }
   677  }
