   679  static bool parser_next(struct parser *parser, struct config_line **line)
   680  {
   681      while (parser->state) {
   682          if (config_buffer_consume(&parser->items, line))
   683              return true;
   684
   685          lwan_strbuf_reset(&parser->strbuf);
   686
   687          parser->state = parser->state(parser);
   688      }
   689
   690      return config_buffer_consume(&parser->items, line);
   691  }
