   693  static struct config *
   694  config_open_path(const char *path, void **data, size_t *size)
   695  {
   696      struct config *config;
   697      struct stat st;
   698      void *mapped;
   699      int fd;
   700
   701      fd = open(path, O_RDONLY | O_CLOEXEC);
   702      if (fd < 0) {
   703          lwan_status_perror("Could not open configuration file: %s", path);
   704          return NULL;
   705      }
   706
   707      if (fstat(fd, &st) < 0) {
   708          close(fd);
   709          return NULL;
   710      }
   711
   712      mapped = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_SHARED, fd, 0);
   713      close(fd);
   714      if (mapped == MAP_FAILED)
   715          return NULL;
   716
   717      config = malloc(sizeof(*config));
   718      if (!config) {
   719          munmap(mapped, (size_t)st.st_size);
   720          return NULL;
   721      }
   722
   723      *data = config->mapped.addr = mapped;
   724      *size = config->mapped.sz = (size_t)st.st_size;
   725
   726      return config;
   727  }
